        if (   def->bridge_params.path_cost
            || def->bridge_params.port_priority
            || def->bridge_hairpin != NETPLAN_TRISTATE_UNSET
            || def->bridge_learning != NETPLAN_TRISTATE_UNSET
            || def->bridge_neigh_suppress != NETPLAN_TRISTATE_UNSET)
